#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxDeviceRatings(std::vector<int>& ratings) {
        long long inc = 0, exc = 0;
        for (int r : ratings) {
            long long newInc = exc + std::max(0, r);
            long long newExc = std::max(inc, exc);
            inc = newInc;
            exc = newExc;
        }
        return std::max(inc, exc);
    }
};

class Solution {
    public long maxDeviceRatings(int[] ratings) {
        long inc = 0, exc = 0;
        for (int r : ratings) {
            long newInc = exc + Math.max(0, r);
            long newExc = Math.max(inc, exc);
            inc = newInc;
            exc = newExc;
        }
        return Math.max(inc, exc);
    }
}

function maxDeviceRatings(ratings) {
    let inc = 0;
    let exc = 0;
    for (const r of ratings) {
        const newInc = exc + Math.max(0, r);
        const newExc = Math.max(inc, exc);
        inc = newInc;
        exc = newExc;
    }
    return Math.max(inc, exc);
}
